parts.text:
{
  "title": "두부와 함께한 산책 기록",
  "cards": [
    {
      "stamp_id": "stamp:e03",
      "title": "상가 밀집 지역으로 이동",
      "text": "등록 상가가 산재한 구간에서 등록 상가가 모인 구간으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e04",
      "title": "상가 밀집 지역에서의 냄새 맡기",
      "text": "등록 상가가 모인 구간에서 두부가 냄새를 맡았다."
    },
    {
      "stamp_id": "stamp:e06",
      "title": "늘벗근린공원 인근으로 이동",
      "text": "등록 상가가 모인 구간에서 늘벗근린공원 인근으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e07",
      "title": "늘벗근린공원 인근에서의 사진 촬영",
      "text": "늘벗근린공원 인근에서 두부와 함께 사진을 찍었다."
    },
    {
      "stamp_id": "stamp:e13",
      "title": "양재천 인근으로 이동",
      "text": "등록 상가가 적은 구간에서 양재천 인근으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e14",
      "title": "독골근린공원 인근으로 이동",
      "text": "양재천 인근에서 독골근린공원 인근으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e15",
      "title": "상가 적은 구간으로 이동",
      "text": "독골근린공원 인근에서 등록 상가가 적은 구간으로 이동하였다."
    }
  ]
}
